  (r"^(.+) \((pesquisa|extensão|ensino|outro|desenvolvimento); coordenação: (.+)\)$", "{1} ({2*}; coordinator: {3})", "{1} ({2*}; coordinación: {3})", "{1} ({2*} ; coordination : {3})"),
